import java.util.*;

public class Main {
	static int[] mem;
	static int m1, m2;

	public static void main(String[] args) {
		Scanner sc = new Scanner(System.in);
		int n = sc.nextInt();
		int m = sc.nextInt();
		int result = m;
		mem = new int[n];
		List<int[]> list = new ArrayList<>();
		boolean[][] del = new boolean[n][n];
		for (int i = 0; i < n; i++) {
			mem[i] = i;
		}
		for (int i = 0; i < m; i++) {
			int a = sc.nextInt();
			int b = sc.nextInt();
			list.add(new int[] { a, b });
		}
		list.sort((o1, o2) -> o1[1] - o2[1]);
		for (int[] data : list) {
			swap(data[0]);
			if (del[m1][m2]) {
				del[m1][m2] = false;
				del[m2][m1] = false;
				result -= 2;
			} else {
				del[m1][m2] = true;
				del[m2][m1] = true;
			}
		}
		System.out.println(result);
	}

	static void swap(int n1) {
		m1 = mem[n1 - 1];
		m2 = mem[n1];
		mem[n1 - 1] = m2;
		mem[n1] = m1;
	}
}

import java.util.*;
