public class Main {
	static class Edge implements Comparable<Edge> {
		int from;
		int to;
		int weight;
		Edge(int from, int to, int weight) {
			super();
			this.from = from;
			this.to = to;
			this.weight = weight;
		}
		@Override
		public int compareTo(Edge o) {
			return this.weight - o.weight;	//가중치 기준 오름차순
		}
	}
	static void makeSets() {
		for(int i = 0; i < V; i++) {
			parents[i] = i;
		}
	}
	static int find(int a) {			// a가 속한 집합의 대표자 리턴
		if(a == parents[a])
			return a;
		return parents[a] = find(parents[a]);	// pass compression
	}
	static boolean union(int a, int b) {	// a, b가 속한 집합 합치기 (union에 성공하면 True, 실패하면 False 반환)
		int aRoot = find(a);
		int bRoot = find(b);
		if(aRoot == bRoot)
			return false;
		parents[bRoot] = aRoot;
		return true;
	}
	static Edge[] edgeList;
	static int[] parents;
	static int V, E;
	public static void main(String[] args) throws IOException {
		BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
		StringTokenizer st = new StringTokenizer(br.readLine());
		V = Integer.parseInt(st.nextToken());
		E = Integer.parseInt(st.nextToken());
		parents = new int[V];
		edgeList = new Edge[E];
		for(int i = 0; i < E; i++) {
			st = new StringTokenizer(br.readLine());
			edgeList[i] = new Edge(Integer.parseInt(st.nextToken()), Integer.parseInt(st.nextToken()), Integer.parseInt(st.nextToken()));
		}	// 간선리스트 생성
		Arrays.sort(edgeList);
		makeSets();		// 모든 정점을 루트로 하는 트리로 만듬
		int result = 0;	// MST 비용
		int cnt = 0;	// 사용된 간선 수
		for(Edge edge : edgeList) {
			if(union(edge.from, edge.to)) {
				cnt++;
				result += edge.weight;
				if(cnt == V - 1)
					break;
			}
		}
		System.out.println(result);
	}
}

